    public void testHtmlComplexAttributesAndSelfClosing() {
        // Testing how it handles attributes with special characters
        Element element = new Element(Tag.valueOf("img"), "");
        element.attr("src", "https://example.com/image.png");
        element.attr("alt", "an image");

        // img is a void element in many parsers, but in Jsoup Element.html() 
        // produces the full tag based on the tag definition.
        String html = element.html();
        assertTrue(html.contains("<img"));
        assertTrue(html.contains("src=\"https://example.com/image.png\""));
        assertTrue(html.contains("alt=\"an image\""));
    }

