    public void testHtml_TrimmingBehavior() {
        // The method calls .trim() on the resulting string.
        // We create a scenario where the internal StringBuilder might have leading/trailing whitespace
        // although jsoup's internal html(appendable) usually doesn't add extra padding.
        Element element = new Element(Tag.valueOf("div"), "");
        element.appendText("Content");
        String result = element.html();

        // Ensure no leading/trailing whitespace remains from the trim() call
        assertEquals("<div>Content</div>", result);
        assertFalse(result.startsWith(" "));
        assertFalse(result.endsWith(" "));
    }

