@Test
    public void testNullValue_WithDeferredName_AndSerializeNullsFalse() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.setSerializeNulls(false);

        // Use name() to set deferredName
        writer.name("testKey");

        // When serializeNulls is false, it should skip the name and the value
        writer.nullValue();

        // The deferredName should be cleared, and nothing should be written to the output for this call
        assertEquals("", out.toString());

        // Verify that the writer is still functional and deferredName was cleared by writing something else
        writer.value("nextValue");
        // If deferredName was cleared, it should just write the next value (depending on context, 
        // but here we just check if it didn't crash and didn't print "testKey")
        assertFalse(out.toString().contains("testKey"));
    }

