@Test
    public void testRenderWrappedText_MultipleWraps() throws Exception {
        StringBuffer sb = new StringBuffer();
        // Text: "One Two Three Four Five"
        // Width: 8
        // Tab: 2
        // 1. findWrapPos("One Two Three Four Five", 8, 0) -> pos is at index 7 (after "One Two")
        // 2. sb.append("One Two").append("\n")
        // 3. text = "  " + "Three Four Five"
        // 4. findWrapPos("  Three Four Five", 8, 2) -> pos is at index 7 (after "  Three")
        // 5. sb.append("  Three").append("\n")
        // 6. text = "  " + "Four Five"
        // 7. findWrapPos("  Four Five", 8, 2) -> pos is -1
        // 8. sb.append("  Four Five")
        String text = "One Two Three Four Five";
        int width = 8;
        int nextLineTabStop = 2;
        formatter.setNewLine("\n");

        StringBuffer result = invokeRenderWrappedText(sb, width, nextLineTabStop, text);

        assertEquals("One Two\n  Three\n  Four Five", result.toString());
    }

