@Test
    public void testAppendComplexStructure() {
        Element parent = new Element(Tag.valueOf("ul"), "");
        String html = "<li>Item 1</li><li class='active'>Item 2</li>";

        parent.append(html);

        Assert.assertEquals(2, parent.children().size());
        Assert.assertTrue(parent.child(1).hasClass("active"));
        Assert.assertEquals("Item 1", parent.child(0).text());
        Assert.assertEquals("Item 2", parent.child(1).text());
    }
